class Labyrint:
    def __init__(self):
        self.rum = {
            "Verkstad": {"söder": "Teknikrum", "norr": "Vardagsrum"},
            "Teknikrum": {"norr": "Verkstad", "öster": "Balkong", "väster": "Hemmab kontor"},
            "Balkong": {"väster": "Teknikrum"},
            "Hemmab kontor": {"norr": "Skafferi", "öster": "Teknikrum", "väster": "Galleri"},
            "Skafferi": {"söder": "Hemmab kontor", "väster": "Vardagsrum"},
            "Galleri": {"söder": "Vardagsrum", "öster": "Hemmab kontor"},
            "Vardagsrum": {"norr": "Galleri", "öster": "Skafferi", "väster": "Verkstad"}
        }
        self.besökta = set()
        self.kö = deque()
        self.start_rum = "Verkstad"
        self.kö.append((self.start_rum, []))
        self.besökta.add(self.start_rum)

    def hitta_kortaste_vägen(self):
        while self.kö:
            nuvarande_rum, väg = self.kö.popleft()
            for riktning, granne in self.rum[nuvarande_rum].items():
                if granne not in self.besökta:
                    self.besökta.add(granne)
                    ny_väg = väg + [riktning]
                    self.kö.append((granne, ny_väg))
                    if len(self.besökta) == len(self.rum):
                        return ny_väg
        return väg

    def simulera_utforskning(self):
        väg = self.hitta_kortaste_vägen()
        nuvarande_rum = self.start_rum
        besökta_rum = {nuvarande_rum}
        steg = 0

        print(f"Du befinner dig i {nuvarande_rum}. För närvarande tillg

